begin;
set local search_path=public,extensions;
select no_plan();
select set_config('test.a',gen_random_uuid()::text,true);
select set_config('test.b',gen_random_uuid()::text,true);
select set_config('test.tech',gen_random_uuid()::text,true);
insert into auth.users(id) values(current_setting('test.a')::uuid),(current_setting('test.b')::uuid),(current_setting('test.tech')::uuid);
set local role authenticated;
select set_config('request.jwt.claim.sub',current_setting('test.a'),true);
select set_config('test.shop',create_initial_shop('Phase 7 rollback fixture')::text,true);
insert into customers(shop_id,first_name,last_name) values(current_setting('test.shop')::uuid,'Repair','Fixture');
select set_config('test.customer',(select id::text from customers),true);
insert into vehicles(shop_id,customer_id,mileage) values(current_setting('test.shop')::uuid,current_setting('test.customer')::uuid,10000);
select set_config('test.vehicle',(select id::text from vehicles),true);
insert into appointments(shop_id,customer_id,vehicle_id,scheduled_start) values(current_setting('test.shop')::uuid,current_setting('test.customer')::uuid,current_setting('test.vehicle')::uuid,now());
select set_config('test.appointment',(select id::text from appointments),true);
insert into work_orders(shop_id,customer_id,vehicle_id,appointment_id,mileage_in,status) values(current_setting('test.shop')::uuid,current_setting('test.customer')::uuid,current_setting('test.vehicle')::uuid,current_setting('test.appointment')::uuid,10000,'open');
select set_config('test.job',(select id::text from work_orders),true);
select set_config('test.member',(select id::text from shop_members),true);
select set_config('test.inspection',create_inspection(current_setting('test.job')::uuid,'multipoint','',gen_random_uuid(),current_setting('test.member')::uuid)::text,true);
select set_config('test.finding',(select id::text from inspection_items order by sort_order limit 1),true);
update inspection_items set condition='attention',recommendation='Check brake service' where id=current_setting('test.finding')::uuid;
select set_config('test.retry',gen_random_uuid()::text,true);
select lives_ok($$select manage_repair(current_setting('test.job')::uuid,'recommend',jsonb_build_object('title','Brake recommendation','description','Customer explanation','priority','high','inspection_item_id',current_setting('test.finding'),'request_key',current_setting('test.retry')))$$,'recommendation from inspection finding');
select set_config('test.recommendation',(select id::text from service_recommendations),true);
select lives_ok($$select manage_repair(current_setting('test.job')::uuid,'recommend',jsonb_build_object('title','Retry','request_key',current_setting('test.retry')))$$,'recommendation retry accepted');
select is((select count(*) from service_recommendations),1::bigint,'recommendation retry does not duplicate');
select is((select inspection_id::text from service_recommendations),current_setting('test.inspection'),'source inspection derived from finding');
select lives_ok($$select manage_repair(current_setting('test.job')::uuid,'from_recommendation',jsonb_build_object('id',current_setting('test.recommendation')))$$,'recommendation becomes estimate service');
select set_config('test.service',(select id::text from work_order_services),true);
select lives_ok($$select manage_repair(current_setting('test.job')::uuid,'service',jsonb_build_object('id',current_setting('test.service'),'description','Brake repair','customer_description','Replace worn brake pads','labor_hours','1.50','labor_rate','120','fees_amount','5'))$$,'service pricing saved');
select lives_ok($$select manage_repair(current_setting('test.job')::uuid,'part',jsonb_build_object('service_id',current_setting('test.service'),'part_name','Brake pad','quantity','2','unit_price','45.55','unit_cost','13.37','request_key',gen_random_uuid()))$$,'structured part saved');
select is((select labor_amount from work_order_services),180.00::numeric,'labor calculated exactly');
select is((select amount from work_order_parts),91.10::numeric,'parts calculated exactly');
select is((select total_amount from work_order_services),276.10::numeric,'service includes labor parts and fees');
select throws_ok($$select unit_cost from work_order_parts$$,'42501',null,'internal cost excluded from client column grants');
select throws_ok($$update work_order_services set total_amount=1$$,'42501',null,'client cannot forge service totals');
select throws_ok($$select manage_repair(current_setting('test.job')::uuid,'part',jsonb_build_object('service_id',current_setting('test.service'),'part_name','Negative','quantity','-1','unit_price','5','request_key',gen_random_uuid()))$$,'22023',null,'negative quantity rejected');
select throws_ok($$select manage_repair(current_setting('test.job')::uuid,'part',jsonb_build_object('service_id',current_setting('test.service'),'part_name','Zero','quantity','0','unit_price','5','request_key',gen_random_uuid()))$$,'23514',null,'zero quantity rejected');
select lives_ok($$select manage_repair(current_setting('test.job')::uuid,'service',jsonb_build_object('description','Optional repair','sort_order',10,'labor_hours','1','labor_rate','60','request_key',gen_random_uuid()))$$,'manual service created');
select set_config('test.declined',(select id::text from work_order_services where recommendation_id is null),true);
select set_config('test.est',(manage_repair(current_setting('test.job')::uuid,'draft','{}')->>'id'),true);
select matches((select estimate_number from work_order_estimates),'^EST-[0-9]{4}-[0-9]{6,}$','professional estimate number');
select is((select grand_total from work_order_estimates),336.10::numeric,'estimate numeric total correct');
select lives_ok($$select manage_repair(current_setting('test.job')::uuid,'estimate_notes','{"customer_note":"Visible note","internal_note":"NEVER_EXPOSE_INTERNAL"}')$$,'draft notes saved');
select set_config('test.token',(manage_repair(current_setting('test.job')::uuid,'present','{}')->>'token'),true);
select is(length(current_setting('test.token')),64,'256-bit hex approval token');
select is((select status from work_orders),'waiting_approval','presentation moves job to waiting approval');
select throws_ok($$update work_orders set status='approved'$$,'22023',null,'direct status edit cannot bypass customer decisions');
select throws_ok($$select token_hash from customer_approval_requests$$,'42501',null,'token hash not exposed to ordinary clients');
select throws_ok($$select manage_repair(current_setting('test.job')::uuid,'service',jsonb_build_object('id',current_setting('test.service'),'description','Overwrite price','labor_rate','1'))$$,'22023',null,'presented pricing cannot be edited');
select throws_ok($$update work_order_estimate_items set description='Forged'$$,'42501',null,'snapshot direct mutation denied');
reset role;
insert into shop_members(shop_id,user_id,role) values(current_setting('test.shop')::uuid,current_setting('test.tech')::uuid,'technician');
set local role authenticated;
select set_config('request.jwt.claim.sub',current_setting('test.tech'),true);
select is((select count(*) from work_order_services),2::bigint,'technician can read repair lines');
select is((select count(*) from work_order_parts),1::bigint,'technician can read required parts');
select throws_ok($$select manage_repair(current_setting('test.job')::uuid,'revise','{}')$$,'42501',null,'technician cannot manage estimates');
select throws_ok($$select record_staff_approval(current_setting('test.est')::uuid,'[]','Name','',true,'phone')$$,'42501',null,'technician cannot record staff authorization');
select set_config('request.jwt.claim.sub',current_setting('test.b'),true);
select set_config('test.other_shop',create_initial_shop('Phase 7 other shop')::text,true);
select is((select count(*) from work_order_services),0::bigint,'cross-shop services hidden');
select is((select count(*) from work_order_parts),0::bigint,'cross-shop parts hidden');
select is((select count(*) from work_order_estimates),0::bigint,'cross-shop estimates hidden');
select is((select count(*) from customer_approval_requests),0::bigint,'cross-shop approval requests hidden');
select throws_ok($$select manage_repair(current_setting('test.job')::uuid,'draft','{}')$$,'42501',null,'cross-shop management denied');
select set_config('request.jwt.claim.sub','',true);
set local role anon;
select throws_ok($$select * from work_order_estimates$$,'42501',null,'anonymous estimate table access denied');
select throws_ok($$select * from work_order_services$$,'42501',null,'anonymous service table access denied');
select throws_ok($$select * from customer_approval_audits$$,'42501',null,'anonymous audit table access denied');
select is(read_customer_approval('invalid'),null::jsonb,'invalid token denied');
select is(read_customer_approval(repeat('0',64)),null::jsonb,'unknown token denied');
select is(read_customer_approval(current_setting('test.token'))->>'grand_total','336.10','valid token returns customer total');
select ok(read_customer_approval(current_setting('test.token'))::text not like '%NEVER_EXPOSE_INTERNAL%','internal notes never exposed');
select ok(read_customer_approval(current_setting('test.token'))::text not like '%unit_cost%','internal cost field never exposed');
select ok(read_customer_approval(current_setting('test.token'))::text not like '%13.37%','internal acquisition cost never exposed');
select ok(read_customer_approval(current_setting('test.token'))::text not like '%'||current_setting('test.job')||'%','database job ID never exposed');
select throws_ok($$select submit_customer_approval(current_setting('test.token'),'[{"line":999,"decision":"approved"},{"line":2,"decision":"declined"}]','Customer','',true)$$,'22023',null,'substituted line number denied');
select throws_ok($$select submit_customer_approval(current_setting('test.token'),'[{"line":1,"decision":"approved"},{"line":2,"decision":"pending"}]','Customer','',true)$$,'22023',null,'unresolved decisions rejected atomically');
select is(read_customer_approval(current_setting('test.token'))->>'status','presented','failed decision leaves presentation intact');
set local role authenticated;
select set_config('request.jwt.claim.sub',current_setting('test.a'),true);
select set_config('test.est2',manage_repair(current_setting('test.job')::uuid,'revise','{}')->>'id',true);
select is((select status from work_order_estimates where id=current_setting('test.est')::uuid),'superseded','presented revision superseded');
select is((select version from work_order_estimates where is_current),2,'revision increments version');
select is((select count(distinct estimate_number) from work_order_estimates),1::bigint,'revision retains estimate number');
select is(read_customer_approval(current_setting('test.token')),null::jsonb,'superseded token denied');
select set_config('test.token2',manage_repair(current_setting('test.job')::uuid,'present','{}')->>'token',true);
reset role;
update customer_approval_requests set expires_at=now()-interval '1 second' where estimate_id=current_setting('test.est2')::uuid;
set local role anon;
select set_config('request.jwt.claim.sub','',true);
select is(read_customer_approval(current_setting('test.token2')),null::jsonb,'expired token denied');
select throws_ok($$select submit_customer_approval(current_setting('test.token2'),'[{"line":1,"decision":"approved"},{"line":2,"decision":"declined"}]','Customer','',true)$$,'22023',null,'expired token cannot submit');
set local role authenticated;
select set_config('request.jwt.claim.sub',current_setting('test.a'),true);
select set_config('test.token3',manage_repair(current_setting('test.job')::uuid,'approval_link','{}')->>'token',true);
set local role anon;
select set_config('request.jwt.claim.sub','',true);
select lives_ok($$select submit_customer_approval(current_setting('test.token3'),'[{"line":1,"decision":"approved"},{"line":2,"decision":"declined"}]','Fixture Customer','Approve only brakes',true)$$,'unauthenticated customer partial authorization succeeds');
select is(read_customer_approval(current_setting('test.token3'))->>'status','partially_approved','mixed decisions yield partial approval');
select throws_ok($$select submit_customer_approval(current_setting('test.token3'),'[{"line":1,"decision":"declined"},{"line":2,"decision":"approved"}]','Changed','',true)$$,'22023',null,'responded token cannot rewrite authorization');
set local role authenticated;
select set_config('request.jwt.claim.sub',current_setting('test.a'),true);
select is((select status from work_order_services where id=current_setting('test.service')::uuid),'approved','approved service updated transactionally');
select is((select status from work_order_services where id=current_setting('test.declined')::uuid),'declined','declined service updated transactionally');
select is((select status from work_orders),'approved','resolved partial approval approves job');
select is((select count(*) from customer_approval_audits),1::bigint,'one immutable audit record');
select throws_ok($$update customer_approval_audits set customer_name='Altered'$$,'42501',null,'audit mutation denied');
select throws_ok($$select manage_repair(current_setting('test.job')::uuid,'start',jsonb_build_object('id',current_setting('test.declined')))$$,'22023',null,'declined repair cannot start');
select set_config('request.jwt.claim.sub',current_setting('test.tech'),true);
select lives_ok($$select manage_repair(current_setting('test.job')::uuid,'start',jsonb_build_object('id',current_setting('test.service')))$$,'technician starts approved repair');
select is((select status from work_orders),'in_progress','job in progress');
select throws_ok($$select manage_repair(current_setting('test.job')::uuid,'complete_job','{"mileage_out":10010}')$$,'22023',null,'job cannot complete before services');
select lives_ok($$select manage_repair(current_setting('test.job')::uuid,'complete_service',jsonb_build_object('id',current_setting('test.service'),'completion_note','Fixture repair verified'))$$,'technician completes service with note');
select is((select status from work_order_parts),'installed','approved part becomes installed');
select is((select status from service_recommendations),'completed','performed recommendation retains completion');
select throws_ok($$select manage_repair(current_setting('test.job')::uuid,'complete_job','{"mileage_out":9999}')$$,'22023',null,'mileage regression rejected');
select lives_ok($$select manage_repair(current_setting('test.job')::uuid,'complete_job','{"mileage_out":10010}')$$,'complete work order with valid mileage');
select is((select status from work_orders),'completed','job completed');
select ok((select completed_at is not null from work_orders),'completion time retained');
select is((select mileage from vehicles),10010,'vehicle mileage advances');
select is((select status from appointments),'completed','linked appointment completes');
select throws_ok($$select manage_repair(current_setting('test.job')::uuid,'start',jsonb_build_object('id',current_setting('test.service')))$$,'22023',null,'completed job cannot restart');
select set_config('request.jwt.claim.sub',current_setting('test.a'),true);
select throws_ok($$update work_orders set technician_notes='Rewrite history'$$,'22023',null,'completed work order locked');
-- Existing Phase 5 jobs may already be waiting or approved before their first structured estimate.
insert into work_orders(shop_id,customer_id,vehicle_id,status) values(current_setting('test.shop')::uuid,current_setting('test.customer')::uuid,current_setting('test.vehicle')::uuid,'open');
select set_config('test.legacy',(select id::text from work_orders where status='open'),true);
update work_orders set status='diagnosing' where id=current_setting('test.legacy')::uuid;
update work_orders set status='waiting_approval' where id=current_setting('test.legacy')::uuid;
select manage_repair(current_setting('test.legacy')::uuid,'service',jsonb_build_object('description','Legacy waiting repair','request_key',gen_random_uuid()));
select manage_repair(current_setting('test.legacy')::uuid,'draft','{}');
select lives_ok($$select manage_repair(current_setting('test.legacy')::uuid,'present','{}')$$,'existing waiting job can present its first estimate');
insert into work_orders(shop_id,customer_id,vehicle_id,status) values(current_setting('test.shop')::uuid,current_setting('test.customer')::uuid,current_setting('test.vehicle')::uuid,'open');
select set_config('test.legacy',(select id::text from work_orders where status='open'),true);
update work_orders set status='diagnosing' where id=current_setting('test.legacy')::uuid;
update work_orders set status='waiting_approval' where id=current_setting('test.legacy')::uuid;
update work_orders set status='approved' where id=current_setting('test.legacy')::uuid;
select manage_repair(current_setting('test.legacy')::uuid,'service',jsonb_build_object('description','Legacy approved repair','request_key',gen_random_uuid()));
select manage_repair(current_setting('test.legacy')::uuid,'draft','{}');
select lives_ok($$select manage_repair(current_setting('test.legacy')::uuid,'present','{}')$$,'existing approved job can request fresh customer decisions');
select is((select status from work_orders where id=current_setting('test.legacy')::uuid),'waiting_approval','legacy approval does not authorize new repair lines');
reset role;
select set_config('request.jwt.claim.sub','',true);
select lives_ok($$delete from auth.users where id=current_setting('test.a')::uuid$$,'removing a staff account preserves presented estimate history');
select is((select created_by from work_order_estimates where id=current_setting('test.est2')::uuid),null::uuid,'removed staff reference cleared without rewriting estimate');
select is((select grand_total from work_order_estimates where id=current_setting('test.est2')::uuid),336.10::numeric,'historical price survives staff removal');
select * from finish();
rollback;
